using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Accepts an OAuth authorization request. Returns an HTTP URL to open after successful authorization.
    /// May return an empty link if just a toast about successful login has to be shown
    /// </summary>
    public Task<TdLib.TdApi.Objects.HttpUrl> AcceptOauthRequestAsync(string url = default, string matchCode = default, bool allowWriteAccess = default, bool allowPhoneNumberAccess = default)
    {

           using var activity =  StartCallActivity("AcceptOauthRequestAsync", typeof(AcceptOauthRequest).FullName ?? "AcceptOauthRequestAsync");

           try
           {
             return client.AcceptOauthRequestAsync(url, matchCode, allowWriteAccess, allowPhoneNumberAccess);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd